// Retry a call until it works or the tries run out.
export async function withRetry(call: () => Promise<unknown>, tries: number = 3) {
  let lastError: unknown;
  for (let i = 0; i < tries; i++) {
    try {
      return await call();
    } catch (e) {
      lastError = e;
      await new Promise((r) => setTimeout(r, 200));
    }
  }
  throw lastError;
}
